            end += 1
        if end - r >= 2:
            bar = (set(range(r, end)), row_profiles[r][0], row_profiles[r][1])
            break
        r = end

    if bar is None:
        return [row[:] for row in grid]

    bar_rows, bar_col, palette = bar
