        return [row[:] for row in grid]

    _, source_color, cells = max(components)
    top = min(y for y, x in cells)
    left = min(x for y, x in cells)
    block_height = max(y for y, x in cells) - top + 1
    shape = [(y - top, x - left) for y, x in cells]
    first_top = top - palette.index(source_color) * block_height

    result = [[0] * w for _ in range(h)]
